<script setup>
import { ref,watch,computed } from 'vue'
import { Button,Dialog } from 'frappe-ui'
import { t as tr } from './i18n.mjs'
import { label,delayDays,allocations } from './reconciliation.mjs'
const props=defineProps({modelValue:Boolean,shipment:Object,perform:Function})
const emit=defineEmits(['update:modelValue'])
const l=(zh,en)=>tr(label(zh,en)),form=ref({}),error=ref('')
watch(()=>[props.modelValue,props.shipment],()=>{const s=props.shipment;if(!s)return;form.value={mode:s.mode,stage:s.stage,eta:s.eta||'',containerNo:s.containerNo??(s.mode==='海运'?s.ref:''),waybillNo:s.waybillNo??(s.mode==='空运'?s.ref:''),courierNo:s.courierNo||'',carrier:tr(s.carrier)||'',location:tr(s.location)||'',chassis:s.chassis||'',position:tr(s.position)||'',delayStatus:s.delayStatus||'unknown',delayReason:s.delayReason||'',nextAction:s.nextAction||'',note:''};error.value=''},{immediate:true})
const days=computed(()=>delayDays({...props.shipment,eta:form.value.eta}))
function save(){try{props.perform(form.value);emit('update:modelValue',false)}catch(e){error.value=e.message}}
</script>
<template><Dialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" :options="{title:l('维护物流与延期','Edit logistics & delay'),size:'xl'}"><template #body-content><div v-if="shipment" class="ops"><div class="ops-review-context"><b>{{shipment.id}}</b><p>{{l('平台协作信息 · 保存后更新所有关联订单','Platform collaboration · updates all linked orders')}}</p><small>{{l('关联订单行','Linked order lines')}}: {{allocations(shipment).length}} · SAP {{shipment.sapDelivery||'—'}}</small></div><div class="ops-form-grid"><label>{{l('运输方式','Transport mode')}}<select v-model="form.mode"><option value="海运">{{tr('海运')}}</option><option value="空运">{{tr('空运')}}</option><option value="快递">{{l('快递','Courier')}}</option></select></label><label>{{l('承运商／快递公司','Carrier / courier company')}}<input v-model="form.carrier"/></label><label>{{l('集装箱号','Container number')}}<input v-model="form.containerNo" placeholder="DEMO-CONTAINER"/></label><label>{{l('提单／空运单号','Bill of lading / air waybill')}}<input v-model="form.waybillNo"/></label><label>{{l('快递追踪号','Courier tracking number')}}<input v-model="form.courierNo"/></label><label>{{l('澳洲到仓 ETA','AU warehouse ETA')}}<input v-model="form.eta" type="date"/><small>{{l('首次 ETA','First ETA')}}: {{shipment.originalEta||'—'}} · {{l('延后天数','Days later')}}: {{days??'—'}}</small></label><label>{{l('运输节点','Logistics milestone')}}<select v-model="form.stage"><option :value="0">{{l('报发待核实','Reported, unverified')}}</option><option :value="2">{{tr('在途')}}</option><option :value="3">{{tr('已到港')}}</option></select></label><label>{{l('当前位置','Current location')}}<input v-model="form.location"/></label><label>{{l('车架号','Chassis number')}}<input v-model="form.chassis"/></label><label>{{l('装载位置','Loading position')}}<input v-model="form.position"/></label></div><div class="ops-detail-heading"><h3>{{l('DELAY／延期跟进','DELAY / follow-up')}}</h3><small>{{l('ETA 偏差由程序计算','ETA variance is calculated')}}</small></div><label class="ops-form-label">{{l('人工反馈状态','Reported status')}}<select v-model="form.delayStatus"><option value="normal">{{l('正常','On track')}}</option><option value="delayed">{{l('已知延期','Known delay')}}</option><option value="unknown">{{l('待确认','Unconfirmed')}}</option></select></label><label class="ops-form-label">{{l('延期原因（已知延期或 ETA 延后时必填）','Delay reason (required for reported delay or later ETA)')}}<textarea v-model="form.delayReason" rows="2"></textarea></label><label class="ops-form-label">{{l('下一步处理安排','Next action')}}<textarea v-model="form.nextAction" rows="2"></textarea></label><label class="ops-form-label">{{l('本次更新说明（必填）','Update note (required)')}}<textarea v-model="form.note" rows="2"></textarea></label><p class="ops-note">{{l('不确定的 ETA 可留空。修改会保留旧值与说明；选择“正常”不会消除仍存在的 ETA 延后。SAP 单据与数量保持独立。','Unknown ETA may remain blank. Previous values and notes are retained; selecting On track does not erase a later ETA. SAP documents and quantities remain independent.')}}</p><p v-if="error" role="alert" class="ops-error">{{error}}</p></div></template><template #actions><div class="modal-actions"><Button variant="outline" @click="emit('update:modelValue',false)">{{tr('取消')}}</Button><Button variant="solid" class="primary" @click="save">{{l('保存物流信息','Save logistics')}}</Button></div></template></Dialog></template>
